import java.util.Scanner;

public class Main {
    static final int MAXN = 1 << 20;
    static final int MOD = 1000000007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        boolean[] visitedFlags = new boolean[MAXN];

        int prime = sc.nextInt();
        int factor = sc.nextInt();
        long answer = 1;

        if (factor == 0) {
            for (int i = 1; i < prime; ++i) {
                answer = (answer * prime) % MOD;
            }
            System.out.println(answer);
            sc.close();
            return;
        }

        long invValue;
        for (invValue = 1; (invValue * factor) % prime != 1; ++invValue);

        if (factor == 1)
            answer = prime;

        for (int i = 1; i < prime; ++i) {
            if (!visitedFlags[i]) {
                answer = (answer * prime) % MOD;
                for (long j = i; !visitedFlags[(int)j]; j = (j * invValue) % prime)
                    visitedFlags[(int)j] = true;
            }
        }
        System.out.println(answer);
        sc.close();
    }
}
